def mySqrt(x: int) -> int:
    # handle base cases
    if x < 2:
        return x

    left, right = 1, x // 2

    while left <= right:
        mid = (left + right) // 2
        sq = mid * mid

        if sq == x:
            return mid
        elif sq < x:
            left = mid + 1
        else:
            right = mid - 1

    # right will be the integer square root of x
    return right
